package akogen.fabric.v6;
import java.nio.file.*;import java.util.*;import com.google.gson.*;
public class WorldPerformanceChecks {
 static double run(SyncChecks.Player player,Map<String,Assets.Entry> entries,int frames)throws Exception{Models.Mat view=new Models.Mat();long start=System.nanoTime();for(int f=0;f<frames;f++)World.drawOwner(player,null,entries,view,0,64,0,1,false,0);return (System.nanoTime()-start)/1e6/frames;}
 public static void main(String[] args)throws Exception{Assets.load(Files.readAllBytes(Paths.get(args[0])));Names.loader=WorldPerformanceChecks.class.getClassLoader();Names.names=new JsonParser().parse(new String(Files.readAllBytes(Paths.get(args[1])),"UTF-8")).getAsJsonObject();Map<String,Assets.Entry> entries=new LinkedHashMap<String,Assets.Entry>();for(Assets.Entry e:Assets.entries){e.model=Models.load(e);e.texture=e.layer=new Object();entries.put(e.name,e);}SyncChecks.Player player=new SyncChecks.Player(1,0);Session.mc=new SyncChecks.MC(player);World.sink=new SyncChecks.Sink();World.buffers=new SyncChecks.Buffer();for(int i=0;i<3;i++)run(player,entries,30);double[] times=new double[5];com.sun.management.ThreadMXBean bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();long tid=Thread.currentThread().getId(),before=bean.getThreadAllocatedBytes(tid);for(int i=0;i<5;i++)times[i]=run(player,entries,60);long bytes=bean.getThreadAllocatedBytes(tid)-before;Arrays.sort(times);System.out.printf(java.util.Locale.ROOT,"WORLD_BENCH median_ms=%.3f allocation_kb_per_frame=%.1f cosmetics=%d%n",times[2],bytes/300d/1024,entries.size());}
}
